15: // ====================================================================
16: // --- process priority (niceness)
17: // ====================================================================
18: 
19: 
20: enum {
21:     IOPRIO_WHO_PROCESS = 1,
22: };
23: 
24: static inline int
25: ioprio_get(int which, int who) {
26:     return syscall(__NR_ioprio_get, which, who);
27: }
28: 
29: static inline int
30: ioprio_set(int which, int who, int ioprio) {
31:     return syscall(__NR_ioprio_set, which, who, ioprio);
32: }
33: 
34: #define IOPRIO_CLASS_SHIFT 13
35: #define IOPRIO_PRIO_MASK ((1UL << IOPRIO_CLASS_SHIFT) - 1)
36: 
37: #define IOPRIO_PRIO_CLASS(mask) ((mask) >> IOPRIO_CLASS_SHIFT)
38: #define IOPRIO_PRIO_DATA(mask) ((mask) & IOPRIO_PRIO_MASK)
39: #define IOPRIO_PRIO_VALUE(class, data) (((class) << IOPRIO_CLASS_SHIFT) | data)
40: 
41: // Return a (ioclass, iodata) Python tuple representing process I/O
42: // priority.
43: PyObject *
44: psutil_proc_ioprio_get(PyObject *self, PyObject *args) {
45:     pid_t pid;
46:     int ioprio, ioclass, iodata;
47:     if (!PyArg_ParseTuple(args, _Py_PARSE_PID, &pid))
48:         return NULL;
49:     ioprio = ioprio_get(IOPRIO_WHO_PROCESS, pid);
50:     if (ioprio == -1)
51:         return psutil_oserror();
52:     ioclass = IOPRIO_PRIO_CLASS(ioprio);
53:     iodata = IOPRIO_PRIO_DATA(ioprio);
54:     return Py_BuildValue("ii", ioclass, iodata);
55: }
56: 
57: 
58: // A wrapper around ioprio_set(); sets process I/O priority. ioclass
59: // can be either IOPRIO_CLASS_RT, IOPRIO_CLASS_BE, IOPRIO_CLASS_IDLE or
60: // 0. iodata goes from 0 to 7 depending on ioclass specified.
61: PyObject *
62: psutil_proc_ioprio_set(PyObject *self, PyObject *args) {
63:     pid_t pid;
64:     int ioprio, ioclass, iodata;
65:     int retval;
66: 
67:     if (!PyArg_ParseTuple(args, _Py_PARSE_PID "ii", &pid, &ioclass, &iodata)) {
68:         return NULL;
69:     }
70:     ioprio = IOPRIO_PRIO_VALUE(ioclass, iodata);
71:     retval = ioprio_set(IOPRIO_WHO_PROCESS, pid, ioprio);
72:     if (retval == -1)
73:         return psutil_oserror();
74:     Py_RETURN_NONE;
75: }
76: 
