79: // --- process CPU affinity
80: // ====================================================================
81: 
82: 
83: #ifdef PSUTIL_HAS_CPU_AFFINITY
84: // Return process CPU affinity as a list of integers.
85: PyObject *
86: psutil_proc_cpu_affinity_get(PyObject *self, PyObject *args) {
87:     int cpu, ncpus, count, cpucount_s;
88:     pid_t pid;
89:     size_t setsize;
90:     cpu_set_t *mask = NULL;
91:     PyObject *py_list = NULL;
92: 
93:     if (!PyArg_ParseTuple(args, _Py_PARSE_PID, &pid))
94:         return NULL;
95: 
96:     // The minimum number of CPUs allocated in a cpu_set_t.
97:     ncpus = sizeof(unsigned long) * CHAR_BIT;
98:     while (1) {
99:         setsize = CPU_ALLOC_SIZE(ncpus);
100:         mask = CPU_ALLOC(ncpus);
101:         if (mask == NULL) {
102:             psutil_debug("CPU_ALLOC() failed");
103:             return PyErr_NoMemory();
104:         }
105:         if (sched_getaffinity(pid, setsize, mask) == 0)
106:             break;
107:         CPU_FREE(mask);
108:         if (errno != EINVAL)
109:             return psutil_oserror();
110:         if (ncpus > INT_MAX / 2) {
111:             PyErr_SetString(
112:                 PyExc_OverflowError,
113:                 "could not allocate "
114:                 "a large enough CPU set"
115:             );
116:             return NULL;
117:         }
118:         ncpus = ncpus * 2;
119:     }
120: 
121:     py_list = PyList_New(0);
122:     if (py_list == NULL)
123:         goto error;
124: 
125:     cpucount_s = CPU_COUNT_S(setsize, mask);
126:     for (cpu = 0, count = cpucount_s; count; cpu++) {
127:         if (CPU_ISSET_S(cpu, setsize, mask)) {
128:             if (!pylist_append_obj(py_list, PyLong_FromLong(cpu)))
129:                 goto error;
130:             --count;
131:         }
132:     }
133:     CPU_FREE(mask);
134:     return py_list;
135: 
136: error:
137:     if (mask)
138:         CPU_FREE(mask);
139:     Py_XDECREF(py_list);
140:     return NULL;
141: }
142: 
