144: // Set process CPU affinity; expects a bitmask.
145: PyObject *
146: psutil_proc_cpu_affinity_set(PyObject *self, PyObject *args) {
147:     cpu_set_t cpu_set;
148:     size_t len;
149:     pid_t pid;
150:     Py_ssize_t i, seq_len;
151:     PyObject *py_cpu_set;
152: 
153:     if (!PyArg_ParseTuple(args, _Py_PARSE_PID "O", &pid, &py_cpu_set))
154:         return NULL;
155: 
156:     if (!PySequence_Check(py_cpu_set)) {
157:         return PyErr_Format(
158:             PyExc_TypeError,
159:             "sequence argument expected, got %R",
160:             Py_TYPE(py_cpu_set)
161:         );
162:     }
163: 
164:     seq_len = PySequence_Size(py_cpu_set);
165:     if (seq_len < 0) {
166:         return NULL;
167:     }
168:     CPU_ZERO(&cpu_set);
169:     for (i = 0; i < seq_len; i++) {
170:         PyObject *item = PySequence_GetItem(py_cpu_set, i);
171:         if (!item) {
172:             return NULL;
173:         }
174:         long value = PyLong_AsLong(item);
175:         Py_XDECREF(item);
176:         if ((value == -1) || PyErr_Occurred()) {
177:             if (!PyErr_Occurred())
178:                 PyErr_SetString(PyExc_ValueError, "invalid CPU value");
179:             return NULL;
180:         }
181:         CPU_SET(value, &cpu_set);
182:     }
183: 
184:     len = sizeof(cpu_set);
185:     if (sched_setaffinity(pid, len, &cpu_set)) {
186:         return psutil_oserror();
187:     }
188: 
189:     Py_RETURN_NONE;
190: }
191: #endif  // PSUTIL_HAS_CPU_AFFINITY

