33: static inline uint32_t
34: psutil_ethtool_cmd_speed(const struct ethtool_cmd *ecmd) {
35: #if LINUX_VERSION_CODE < KERNEL_VERSION(2, 6, 27)
36:     return ecmd->speed;
37: #else
38:     return (ecmd->speed_hi << 16) | ecmd->speed;
39: #endif
40: }
41: 
42: // May happen on old RedHat versions, see:
43: // https://github.com/giampaolo/psutil/issues/607
44: #ifndef DUPLEX_UNKNOWN
45: #define DUPLEX_UNKNOWN 0xff
46: #endif
47: 
