55: // * http://www.i-scream.org/libstatgrab/
56: PyObject *
57: psutil_net_if_duplex_speed(PyObject *self, PyObject *args) {
58:     char *nic_name;
59:     int sock = 0;
60:     int ret;
61:     int duplex;
62:     __u32 uint_speed;
63:     int speed;
64:     struct ifreq ifr;
65:     struct ethtool_cmd ethcmd;
66:     PyObject *py_retlist = NULL;
67: 
68:     if (!PyArg_ParseTuple(args, "s", &nic_name))
69:         return NULL;
70: 
71:     sock = socket(AF_INET, SOCK_DGRAM, 0);
72:     if (sock == -1)
73:         return psutil_oserror_wsyscall("socket()");
74:     str_copy(ifr.ifr_name, sizeof(ifr.ifr_name), nic_name);
75: 
76: 
77:     // duplex and speed
78:     memset(&ethcmd, 0, sizeof ethcmd);
79:     ethcmd.cmd = ETHTOOL_GSET;
80:     ifr.ifr_data = (void *)&ethcmd;
81:     ret = ioctl(sock, SIOCETHTOOL, &ifr);
82: 
83:     if (ret != -1) {
84:         duplex = ethcmd.duplex;
85:         // speed is returned from ethtool as a __u32 ranging from 0 to INT_MAX
86:         // or SPEED_UNKNOWN (-1)
87:         uint_speed = psutil_ethtool_cmd_speed(&ethcmd);
88:         if (uint_speed == (__u32)SPEED_UNKNOWN || uint_speed > INT_MAX) {
89:             speed = 0;
90:         }
91:         else {
92:             speed = (int)uint_speed;
93:         }
94:     }
95:     else {
96:         if ((errno == EOPNOTSUPP) || (errno == EINVAL) || (errno == EBUSY)) {
97:             // EOPNOTSUPP may occur in case of wi-fi cards.
98:             // For EINVAL see:
99:             // https://github.com/giampaolo/psutil/issues/797
100:             //     #issuecomment-202999532
101:             // EBUSY may occur with broken drivers or busy devices.
102:             duplex = DUPLEX_UNKNOWN;
103:             speed = 0;
104:         }
105:         else {
106:             psutil_oserror_wsyscall("ioctl(SIOCETHTOOL)");
107:             goto error;
108:         }
109:     }
110: 
111:     py_retlist = Py_BuildValue("[ii]", duplex, speed);
112:     if (!py_retlist)
113:         goto error;
114:     close(sock);
115:     return py_retlist;
116: 
117: error:
118:     if (sock != -1)
119:         close(sock);
120:     return NULL;
121: }

