31: // psutil_heap_info() -> (heap_used, mmap_used)
32: // Return low-level heap statistics from the C allocator (glibc).
33: PyObject *
34: psutil_heap_info(PyObject *self, PyObject *args) {
35:     static int warned = 0;
36:     void *handle = NULL;
37:     void *fun = NULL;
38:     unsigned long long uord, mmap;
39: 
40:     handle = dlopen("libc.so.6", RTLD_LAZY);
41:     if (handle != NULL) {
42:         fun = dlsym(handle, "mallinfo2");
43:     }
44: 
45:     // mallinfo2() appeared in glibc 2.33, February 2021.
46:     if (fun != NULL) {
47:         struct my_mallinfo2 m2;
48: 
49:         m2 = ((struct my_mallinfo2(*)(void))fun)();
50: 
51:         uord = (unsigned long long)m2.uordblks;
52:         mmap = (unsigned long long)m2.hblkhd;
53:     }
54: 
55:     // mallinfo() is broken due to its fields that are 32-bit
56:     // integers, meaning they overflow if process allocates more than
57:     // 2GB in the heap.
58:     else {
59:         struct mallinfo m1;
60: 
61:         if (!warned) {
62:             psutil_debug("WARNING: using deprecated mallinfo()");
63:             warned = 1;
64:         }
65: 
66: #pragma GCC diagnostic push
67: #pragma GCC diagnostic ignored "-Wdeprecated-declarations"
68:         m1 = mallinfo();
69: #pragma GCC diagnostic pop
70: 
71:         uord = (unsigned long long)m1.uordblks;
72:         mmap = (unsigned long long)m1.hblkhd;
73:     }
74: 
75:     if (handle)
76:         dlclose(handle);
77: 
78:     return Py_BuildValue("KK", uord, mmap);
79: }
