49: // Translate a sockaddr struct into a Python string.
50: // Return None if address family is not AF_INET* or AF_PACKET.
51: PyObject *
52: psutil_convert_ipaddr(struct sockaddr *addr, int family) {
53:     char buf[NI_MAXHOST];
54:     int err;
55:     int addrlen;
56:     size_t n;
57:     size_t len;
58:     const char *data;
59:     char *ptr;
60: 
61:     if (addr == NULL) {
62:         Py_RETURN_NONE;
63:     }
64:     else if (family == AF_INET || family == AF_INET6) {
65:         if (family == AF_INET)
66:             addrlen = sizeof(struct sockaddr_in);
67:         else
68:             addrlen = sizeof(struct sockaddr_in6);
69:         err = getnameinfo(
70:             addr, addrlen, buf, sizeof(buf), NULL, 0, NI_NUMERICHOST
71:         );
72:         if (err != 0) {
73:             // XXX we get here on FreeBSD when processing 'lo' / AF_INET6
74:             // broadcast. Not sure what to do other than returning None.
75:             // ifconfig does not show anything BTW.
76:             // psutil_runtime_error(gai_strerror(err));
77:             // return NULL;
78:             Py_RETURN_NONE;
79:         }
80:         else {
81:             return PyUnicode_FromString(buf);
82:         }
83:     }
84: #ifdef PSUTIL_LINUX
85:     else if (family == AF_PACKET) {
86:         struct sockaddr_ll *lladdr = (struct sockaddr_ll *)addr;
87:         len = lladdr->sll_halen;
88:         data = (const char *)lladdr->sll_addr;
89:     }
90: #elif defined(PSUTIL_BSD) || defined(PSUTIL_OSX)
91:     else if (addr->sa_family == AF_LINK) {
92:         // Note: prior to Python 3.4 socket module does not expose
93:         // AF_LINK so we'll do.
94:         struct sockaddr_dl *dladdr = (struct sockaddr_dl *)addr;
95:         len = dladdr->sdl_alen;
96:         data = LLADDR(dladdr);
97:     }
98: #endif
99:     else {
100:         // unknown family
101:         Py_RETURN_NONE;
102:     }
103: 
104:     // AF_PACKET or AF_LINK
105:     if (len > 0) {
106:         ptr = buf;
107:         for (n = 0; n < len; ++n) {
108:             str_format(ptr, sizeof(ptr), "%02x:", data[n] & 0xff);
109:             ptr += 3;
110:         }
111:         *--ptr = '\0';
112:         return PyUnicode_FromString(buf);
113:     }
114:     else {
115:         Py_RETURN_NONE;
116:     }
117: }
