147: // Convert the hi and lo parts of a FILETIME structure or a
148: // LARGE_INTEGER to a UNIX time. A FILETIME contains a 64-bit value
149: // representing the number of 100-nanosecond intervals since January 1,
150: // 1601 (UTC). A UNIX time is the number of seconds that have elapsed
151: // since the UNIX epoch, that is the time 00:00:00 UTC on 1 January
152: // 1970.
153: static double
154: _to_unix_time(ULONGLONG hiPart, ULONGLONG loPart) {
155:     ULONGLONG ret;
156: 
157:     // 100 nanosecond intervals since January 1, 1601.
158:     ret = hiPart << 32;
159:     ret += loPart;
160:     // Change starting time to the Epoch (00:00:00 UTC, January 1, 1970).
161:     ret -= 116444736000000000ull;
162:     // Convert nano secs to secs.
163:     return (double)ret / 10000000ull;
164: }
